176	    /** Move a claim to a new status; a change its status does not allow, or one the sheet's
177	     *  permission matrix does not let the user's role make, is refused, as is the user who opened a
178	     *  claim settling it. A clerk settling a claim whose due is above the clerk limit
179	     *  leaves it PENDING a steward's approval instead. */
180	    @Transactional
181	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
182	        Person person = person(sheetId, personId);
183	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
184	        // read below is its latest state.
185	        if (to == ClaimStatus.OPEN) {
186	            sheets.lock(sheetId);
187	        }
188	        Claim claim = claim(sheetId, personId, id);
189	        settings.refuseUnless(sheetId, user, switch (to) {
190	            case OPEN -> Permission.OPEN;
191	            case SETTLED -> Permission.SETTLE;
192	            case VOID -> Permission.VOID;
193	            case DRAFT, PENDING -> throw new StatusChangeRefusedException(claim.getStatus(), to);
194	        });
195	        refuseClosed(sheetId, claim.getDate());
196	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
197	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
198	        if (reversing) {
199	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
200	        } else if (!claim.getStatus().canMoveTo(to)) {
201	            throw new StatusChangeRefusedException(claim.getStatus(), to);
202	        }
203	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
204	            throw new OwnClaimSettleRefusedException(user);
205	        }
206	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
207	            throw new StatusChangeRefusedException(claim.getStatus(), to);
208	        }
209	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
210	        // gathered by then.
211	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
212	        if (to == ClaimStatus.SETTLED) {
213	            refuseUnproved(sheetId, claim, due);
214	        }
215	        if (to == ClaimStatus.OPEN) {
216	            refuseUnnoted(sheetId, person, claim);
217	        }
218	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
219	            to = ClaimStatus.PENDING;
220	        }
221	        claim.setStatus(to);
222	        if (to == ClaimStatus.OPEN) {
223	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
224	            claim.setOpenedBy(user);
225	        } else if (to == ClaimStatus.SETTLED) {
226	            claim.setSettledDue(due);
227	        }
228	        Claim saved = claims.saveAndFlush(claim);
229	        log(sheetId, user, person, saved);
230	        String event = switch (to) {
231	            case OPEN -> "CLAIM_OPENED";
232	            case PENDING -> "CLAIM_PENDING";
233	            case SETTLED -> "CLAIM_SETTLED";
234	            case VOID -> "CLAIM_VOIDED";
235	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
236	        };
237	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
238	        if (to == ClaimStatus.SETTLED) {
239	            line += " due=" + settledDueText(saved);
240	        } else if (reversing) {
241	            line += " reversed=" + settledDueText(saved);
242	        }
243	        audit.recordOnCommit(line);
244	        if (to == ClaimStatus.SETTLED) {
245	            notifyWatchers(sheetId, user, person, saved);
246	        }
247	        return saved;
248	    }
