275	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
276	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
277	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
278	     *  is listed under the person naming the claim it was split from. A claim that is not OPEN, one
279	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
280	     *  user whose role may not open a claim, is refused. */
281	    @Transactional
282	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
283	        Person person = person(sheetId, personId);
284	        // Lock the sheet first, as opening does: the new claim takes the next number.
285	        sheets.lock(sheetId);
286	        Claim claim = claim(sheetId, personId, id);
287	        settings.refuseUnless(sheetId, user, Permission.OPEN);
288	        refuseClosed(sheetId, claim.getDate());
289	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
290	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
291	        }
292	        BigDecimal part = scaled(amount);
293	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
294	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
295	        }
296	        claim.setAmount(claim.getAmount().subtract(part));
297	        claim.unbind();
298	        Claim kept = claims.saveAndFlush(claim);
299	        LocalDate on = kept.getDate();
300	        LocalDate dueBy = on.plusDays(termsFor(sheetId, person, on));
301	        Claim added = claims.saveAndFlush(Claim.splitOff(kept, part, dueBy, nextNumber(sheetId, on), user));
302	        log(sheetId, user, person, added);
303	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
304	                + " into=" + added.getNumber());
305	        record("CLAIM_OPENED", sheetId, user, person, added);
306	        return new Split(kept, added);
