362	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
363	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
364	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
365	     *  one dated in a closed period, is refused. */
366	    @Transactional
367	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
368	        Person person = person(sheetId, personId);
369	        Claim claim = claim(sheetId, personId, id);
370	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
371	            throw new ResettleRefusedException(user);
372	        }
373	        if (claim.getStatus() != ClaimStatus.SETTLED) {
374	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
375	        }
376	        refuseClosed(sheetId, claim.getDate());
377	        String old = settledDueText(claim);
378	        BigDecimal figure = liveFigureOf(sheetId, person, claim, null);
379	        claim.setSettledDue(figure == null ? null
380	                : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, claim, figure, true, null)), null));
381	        Claim saved = claims.saveAndFlush(claim);
382	        log(sheetId, user, person, saved);
383	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
384	                + " old=" + old + " new=" + settledDueText(saved));
385	        notifyWatchers(sheetId, user, person, saved);
386	        return saved;
387	    }
