390	     *  moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
391	     *  number and date, loses any figure a statement bound it to (live again until its new person's
392	     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
393	     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
394	     *  a move to the same person or to one retired before the claim's date, is refused. */
395	    @Transactional
396	    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
397	        Person from = person(sheetId, personId);
398	        Person to = person(sheetId, toPersonId);
399	        Claim claim = claim(sheetId, personId, id);
400	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
401	            throw new ReassignRefusedException(user);
402	        }
403	        if (!claim.getStatus().canReassign()) {
404	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
405	        }
406	        if (from.getId().equals(to.getId())) {
407	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
408	        }
409	        if (claim.isCorrection()) {
